<script setup>
// Pequeños esquemas didácticos en SVG/HTML. Uso: <Diagram kind="rgb" />
const props = defineProps({ kind: { type: String, required: true }, base: { type: Number, default: 200 } })
const rows = computed(() => ({
  tinte: [15, 30, 45, 60, 75, 90].map(l => hsl2hex(props.base, 70, 30 + l * .6)),
  tono: [70, 55, 40, 25, 12, 4].map(s => hsl2hex(props.base, s, 50)),
  sombra: [50, 42, 34, 26, 18, 10].map(l => hsl2hex(props.base, 70, l))
}))
const labels = { tinte: ['Tinte', 'color + blanco: más claro'], tono: ['Tono', 'color + gris: más apagado'], sombra: ['Sombra', 'color + negro: más oscuro'] }
</script>
<template>
  <div class="dg">
    <figure v-if="kind === 'rgb'"><svg viewBox="0 0 200 170" role="img" aria-label="Luz roja, verde y azul que se suman y producen blanco en el centro"><rect width="200" height="170" rx="12" fill="#000" /><g style="isolation:isolate"><circle cx="78" cy="72" r="46" fill="#f00" style="mix-blend-mode:screen" /><circle cx="122" cy="72" r="46" fill="#0f0" style="mix-blend-mode:screen" /><circle cx="100" cy="110" r="46" fill="#00f" style="mix-blend-mode:screen" /></g></svg><figcaption><b>RGB · luz (aditivo)</b> Suma luces y llega al blanco.</figcaption></figure>
    <figure v-else-if="kind === 'ryb'"><svg viewBox="0 0 200 170" role="img" aria-label="Pigmentos rojo, amarillo y azul que se mezclan y oscurecen en el centro"><rect width="200" height="170" rx="12" fill="#f8fafc" /><g style="isolation:isolate"><circle cx="78" cy="72" r="46" fill="#e0243b" style="mix-blend-mode:multiply" /><circle cx="122" cy="72" r="46" fill="#f7d117" style="mix-blend-mode:multiply" /><circle cx="100" cy="110" r="46" fill="#2563eb" style="mix-blend-mode:multiply" /></g></svg><figcaption><b>RYB · pigmento (sustractivo)</b> Mezcla pintura y se oscurece.</figcaption></figure>
    <figure v-else-if="kind === 'temp'" class="wide"><svg viewBox="0 0 400 130" role="img" aria-label="Franja de colores cálidos a fríos. Los cálidos parecen avanzar y los fríos retroceder"><defs><linearGradient id="tg"><stop offset="0" stop-color="#d7263d" /><stop offset=".3" stop-color="#f5a623" /><stop offset=".5" stop-color="#9ccc2a" /><stop offset=".75" stop-color="#0e9aa7" /><stop offset="1" stop-color="#4a4fc4" /></linearGradient></defs><rect x="10" y="60" width="380" height="26" rx="13" fill="url(#tg)" /><circle cx="70" cy="40" r="28" fill="#f2711c" /><circle cx="330" cy="40" r="16" fill="#2563eb" /><text x="70" y="112" text-anchor="middle" fill="#e2e8f0" font-size="13">Cálido: avanza y energiza</text><text x="330" y="112" text-anchor="middle" fill="#e2e8f0" font-size="13">Frío: se aleja y calma</text></svg></figure>
    <div v-else-if="kind === 'tints'" class="tints" aria-label="Tinte, tono y sombra de un color">
      <div v-for="(r, k) in rows" :key="k"><b>{{ labels[k][0] }}</b><span class="mut"> · {{ labels[k][1] }}</span><div class="sws"><i v-for="c in r" :key="c" :style="{ background: c }" /></div></div>
    </div>
    <template v-else-if="kind === 'weight'">
      <figure><svg viewBox="0 0 200 110" role="img" aria-label="Un círculo grande pesa más que uno pequeño"><rect width="200" height="110" rx="12" fill="#0b1220" /><circle cx="62" cy="55" r="34" fill="#94a3b8" /><circle cx="146" cy="55" r="14" fill="#94a3b8" /></svg><figcaption><b>Tamaño</b> Lo grande pesa más.</figcaption></figure>
      <figure><svg viewBox="0 0 200 110" role="img" aria-label="Un círculo saturado pesa más que uno apagado"><rect width="200" height="110" rx="12" fill="#0b1220" /><circle cx="62" cy="55" r="28" fill="#ef4444" /><circle cx="146" cy="55" r="28" fill="#6b4a4a" /></svg><figcaption><b>Saturación</b> El color vivo llama más.</figcaption></figure>
      <figure><svg viewBox="0 0 200 110" role="img" aria-label="Un círculo claro destaca más sobre fondo oscuro que uno oscuro"><rect width="200" height="110" rx="12" fill="#0b1220" /><circle cx="62" cy="55" r="28" fill="#f8fafc" /><circle cx="146" cy="55" r="28" fill="#1e293b" /></svg><figcaption><b>Contraste</b> Lo claro sobre oscuro destaca.</figcaption></figure>
    </template>
    <template v-else-if="kind === 'balance'">
      <figure><svg viewBox="0 0 200 110" role="img" aria-label="Equilibrio simétrico: dos formas iguales a cada lado"><rect width="200" height="110" rx="12" fill="#0b1220" /><line x1="100" y1="10" x2="100" y2="100" stroke="#334155" stroke-dasharray="4 4" /><circle cx="52" cy="55" r="22" fill="#06b6d4" /><circle cx="148" cy="55" r="22" fill="#06b6d4" /></svg><figcaption><b>Simétrico</b> Calma y orden.</figcaption></figure>
      <figure><svg viewBox="0 0 200 110" role="img" aria-label="Equilibrio asimétrico: una forma grande cerca del centro y una pequeña lejos"><rect width="200" height="110" rx="12" fill="#0b1220" /><line x1="100" y1="10" x2="100" y2="100" stroke="#334155" stroke-dasharray="4 4" /><circle cx="76" cy="58" r="30" fill="#ec4899" /><circle cx="162" cy="50" r="11" fill="#eab308" /></svg><figcaption><b>Asimétrico</b> Dinámico y moderno.</figcaption></figure>
      <figure><svg viewBox="0 0 200 110" role="img" aria-label="Equilibrio radial: formas alrededor de un centro"><rect width="200" height="110" rx="12" fill="#0b1220" /><circle cx="100" cy="55" r="12" fill="#eab308" /><g fill="#8b5cf6"><circle cx="100" cy="18" r="9" /><circle cx="100" cy="92" r="9" /><circle cx="63" cy="55" r="9" /><circle cx="137" cy="55" r="9" /></g></svg><figcaption><b>Radial</b> Todo gira al centro.</figcaption></figure>
    </template>
    <figure v-else-if="kind === 'thirds'" class="wide"><svg viewBox="0 0 300 170" role="img" aria-label="Encuadre dividido en nueve partes con cuatro puntos de oro"><rect width="300" height="170" rx="12" fill="#0b1220" /><g stroke="#94a3b8" stroke-dasharray="5 5"><line x1="100" y1="0" x2="100" y2="170" /><line x1="200" y1="0" x2="200" y2="170" /><line x1="0" y1="57" x2="300" y2="57" /><line x1="0" y1="113" x2="300" y2="113" /></g><g fill="none" stroke="#eab308" stroke-width="3"><circle cx="100" cy="57" r="9" /><circle cx="200" cy="57" r="9" /><circle cx="100" cy="113" r="9" /><circle cx="200" cy="113" r="9" /></g><circle cx="200" cy="57" r="16" fill="#f97316" /><path d="M0 150 Q80 110 160 140 T300 125 V170 H0Z" fill="#1f4d36" /></svg><figcaption><b>Regla de tercios</b> El sol vive en un punto de oro, no en el centro.</figcaption></figure>
    <figure v-else-if="kind === 'rhythm'" class="wide"><svg viewBox="0 0 400 110" role="img" aria-label="Círculos que crecen de a poco, un ritmo visual"><rect width="400" height="110" rx="12" fill="#0b1220" /><circle v-for="i in 8" :key="i" :cx="30 + (i - 1) * 48" cy="55" :r="5 + i * 2.8" :fill="hsl2hex(160 + i * 22, 75, 55)" /></svg><figcaption><b>Ritmo</b> Repetir con variación guía la mirada de un lado a otro.</figcaption></figure>
  </div>
</template>
